action.command:
node -e "
const fs = require('fs');
const file = process.env.KIRO_FILE_PATH || '';
if (!file) process.exit(0);
const sql = fs.readFileSync(file, 'utf8');
const tables = (sql.match(/create table (\w+)/gi) || []).map(m => m.replace(/create table /i,''));
const missing = tables.filter(t => !sql.toLowerCase().includes('enable row level security'));
if (missing.length) { console.error('RLS not enabled for tables: ' + missing.join(', ')); process.exit(2); }
console.log('RLS check passed for: ' + tables.join(', '));
"
